file.content:
@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #2a2622;
  background: #fffdf9;
}

a {
  color: inherit;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 18px 64px;
  border-bottom: 1px solid #ece6dc;
}

.logo {
  font-size: 20px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  align-items: center;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  color: #5c544b;
}

.site-nav .nav-signin {
  padding: 10px 22px;
  border-radius: 6px;
  background: #8a3b24;
  color: #ffffff;
  font-weight: 500;
}

.hero {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 64px;
  padding: 64px 64px 48px;
}

.hero-text {
  max-width: 540px;
}

h1 {
  margin: 0 0 16px;
  font-size: 40px;
  font-weight: 500;
  line-height: 1.15;
}

.hero-text p {
  margin: 0 0 28px;
  color: #5c544b;
}

.actions {
  display: flex;
  gap: 12px;
}

.button {
  display: inline-block;
  padding: 10px 18px;
  border-radius: 6px;
  text-decoration: none;
  font-size: 15px;
}

.button-primary {
  border: 1px solid #d6cec2;
  background: #f3eee6;
  color: #5c544b;
}

.button-secondary {
  border: 1px solid #d6cec2;
  background: #fffdf9;
  color: #5c544b;
}

.preview {
  flex: 0 0 480px;
  border: 1px solid #ece6dc;
  border-radius: 8px;
  background: #ffffff;
}

.preview-head {
  display: flex;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid #ece6dc;
  font-weight: 500;
}

.preview-date {
  color: #8a8178;
  font-weight: 400;
  font-size: 14px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

th,
td {
  padding: 9px 18px;
  text-align: left;
  border-bottom: 1px solid #f3eee6;
}

th {
  color: #8a8178;
  font-weight: 400;
}

tbody tr:last-child td {
  border-bottom: none;
}

.facts {
  display: flex;
  gap: 40px;
  padding: 8px 64px 0;
}

.facts p {
  flex: 1;
  margin: 0;
  font-size: 15px;
  color: #5c544b;
}

.fact-title {
  color: #2a2622;
  font-weight: 500;
}

