@font-face {
  font-family: "Inter";
  font-weight: 400;
  src: url("fonts/inter-latin-400-normal.woff2") format("woff2");
}

@font-face {
  font-family: "Inter";
  font-weight: 500;
  src: url("fonts/inter-latin-500-normal.woff2") format("woff2");
}

* {
  box-sizing: border-box;
}

:root {
  /* Side padding that grows on wide screens so the content stays within 1200px. */
  --page-gutter: max(64px, calc((100% - 1200px) / 2));
}

body {
  margin: 0;
  font-family: "Inter", sans-serif;
  font-size: 16px;
  line-height: 1.55;
  color: #2a2622;
  background: #fffdf9;
}

a {
  color: inherit;
}

.site-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 16px;
  padding: 18px var(--page-gutter);
  border-bottom: 1px solid #ece6dc;
}

.logo {
  font-size: 20px;
  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  align-items: center;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  color: #5c544b;
}

.site-nav .nav-signin {
  padding: 8px 18px;
  border: 1px solid #d6cec2;
  border-radius: 6px;
  color: #2a2622;
  font-weight: 500;
}

/*
 * The hero and the notes share one grid of three equal columns.
 * The hero text spans the first two and the table takes the third,
 * so the three notes are equal in width and the third lines up with the table.
 */
.hero,
.facts {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  column-gap: 64px;
  padding-left: var(--page-gutter);
  padding-right: var(--page-gutter);
}

.hero-text {
  grid-column: 1 / 3;
}

.hero {
  align-items: center;
  padding-top: 64px;
  padding-bottom: 48px;
}

.hero-text {
  max-width: 540px;
}

h1 {
  margin: 0 0 16px;
  font-size: 40px;
  font-weight: 500;
  line-height: 1.15;
  /* Spread the lines evenly so the last line never holds a single word. */
  text-wrap: balance;
}

.hero-text p {
  margin: 0 0 28px;
  color: #5c544b;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.button {
  display: inline-block;
  padding: 10px 18px;
  border-radius: 6px;
  text-decoration: none;
  font-size: 16px;
  font-weight: 500;
  /* Keep "30-day" and the other labels on one line. */
  white-space: nowrap;
}

.button-primary {
  border: 1px solid #8a3b24;
  background: #8a3b24;
  color: #ffffff;
}

.button-secondary {
  border: 1px solid #d6cec2;
  background: #fffdf9;
  color: #2a2622;
}

.preview {
  border: 1px solid #ece6dc;
  border-radius: 8px;
  background: #ffffff;
}

.preview-head {
  display: flex;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid #ece6dc;
  font-weight: 500;
}

.preview-date {
  color: #5c544b;
  font-weight: 400;
  font-size: 14px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

th,
td {
  padding: 9px 18px;
  text-align: left;
  border-bottom: 1px solid #f3eee6;
}

th {
  color: #5c544b;
  font-weight: 400;
}

tbody tr:last-child td {
  border-bottom: none;
}

.facts {
  padding-top: 8px;
  padding-bottom: 64px;
}

.facts p {
  margin: 0;
  font-size: 16px;
  color: #5c544b;
  /* Avoid a single word alone on the last line. */
  text-wrap: pretty;
}

.fact-title {
  color: #2a2622;
  font-weight: 500;
}

/* Tablet and phone: stack the hero and the notes in one column. */
@media (max-width: 900px) {
  :root {
    --page-gutter: 32px;
  }

  .hero {
    grid-template-columns: minmax(0, 1fr);
    row-gap: 40px;
    padding-top: 48px;
  }

  /* 560px keeps the paragraphs at 75 characters per line or fewer. */
  .hero-text,
  .preview,
  .facts p {
    max-width: 560px;
  }

  .facts {
    grid-template-columns: minmax(0, 1fr);
    row-gap: 16px;
  }
}

/*
 * Phone: logo and "Sign in" share the top row, the other links go on
 * a second row. "display: contents" lets the nav's links sit directly
 * in the header grid while the nav element stays in the markup.
 */
@media (max-width: 600px) {
  :root {
    --page-gutter: 20px;
  }

  .site-header {
    display: grid;
    grid-template-columns: auto auto auto 1fr;
    column-gap: 20px;
    row-gap: 10px;
    padding-top: 14px;
    padding-bottom: 14px;
  }

  .site-nav {
    display: contents;
  }

  .logo {
    grid-row: 1;
    grid-column: 1 / 4;
  }

  .site-nav a {
    grid-row: 2;
    margin-left: 0;
    white-space: nowrap;
  }

  .site-nav .nav-signin {
    grid-row: 1;
    grid-column: 4;
    justify-self: end;
  }

  h1 {
    font-size: 32px;
  }

  th,
  td {
    padding: 9px 10px;
  }

  /* Keep the column labels and the titles on one line each. */
  th,
  td:first-child {
    white-space: nowrap;
  }
}

