input.new_string:
/*
 * Phone: logo and "Sign in" share the top row, the other links go on
 * a second row. "display: contents" lets the nav's links sit directly
 * in the header's flex row while the nav element stays in the markup.
 * The empty ::after item takes a full row, which forces the line break.
 */
@media (max-width: 600px) {
  :root {
    --page-gutter: 20px;
  }

  .site-header {
    flex-wrap: wrap;
    gap: 10px 20px;
    padding-top: 14px;
    padding-bottom: 14px;
  }

  .site-header::after {
    content: "";
    order: 2;
    flex-basis: 100%;
    height: 0;
    margin-top: -10px;
  }

  .site-nav {
    display: contents;
  }

  .logo {
    order: 0;
    margin-right: auto;
  }

  .site-nav .nav-signin {
    order: 1;
  }

  .site-nav a {
    order: 3;
    margin-left: 0;
    white-space: nowrap;
  }

