  font-weight: 500;
  text-decoration: none;
}

.site-nav {
  display: flex;
  align-items: center;
}

.site-nav a {
  margin-left: 28px;
  text-decoration: none;
  color: #5c544b;
}

.site-nav .nav-signin {
  padding: 8px 18px;
  border: 1px solid #d6cec2;
  border-radius: 6px;
  color: #2a2622;
  font-weight: 500;
}

/*
 * The hero and the notes share one grid of three columns.
 * The hero text takes the first column and the table spans the other two,
 * so the second note lines up with the table. The first column is a
 * quarter wider so the headline breaks into three phrases.
 */
.hero,
.facts {
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr) minmax(0, 1fr);
  column-gap: 48px;
  padding-left: var(--page-gutter);
  padding-right: var(--page-gutter);
}

.preview {
  grid-column: 2 / 4;
}

.hero {
  /* Top-align so the headline and the table start at the same height. */
  align-items: start;
  padding-top: 64px;
  padding-bottom: 48px;
}

.hero-text {
  max-width: 540px;
}

h1 {
  margin: 0 0 16px;
  font-size: 40px;
  font-weight: 500;
  line-height: 1.15;
  /* Spread the lines evenly so the last line never holds a single word. */
  text-wrap: balance;
}

.hero-text p {
  margin: 0 0 28px;
  color: #5c544b;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
}

.button {
  display: inline-block;
  padding: 10px 18px;
  border-radius: 6px;
  text-decoration: none;
  font-size: 16px;
  font-weight: 500;
  /* Keep "30-day" and the other labels on one line. */
  white-space: nowrap;
}

.button-primary {
  border: 1px solid #8a3b24;
  background: #8a3b24;
  color: #ffffff;
}

.button-secondary {
  border: 1px solid #d6cec2;
  background: #fffdf9;
  color: #2a2622;
}

.preview {
  border: 1px solid #ece6dc;
  border-radius: 8px;
  background: #ffffff;
}

.preview-head {
  display: flex;
  justify-content: space-between;
  padding: 14px 18px;
  border-bottom: 1px solid #ece6dc;
  font-weight: 500;
}

.preview-date {
  color: #5c544b;
  font-weight: 400;
  font-size: 14px;
}

table {
  width: 100%;
  border-collapse: collapse;
  font-size: 14px;
}

th,
td {
  padding: 9px 18px;
  text-align: left;
  border-bottom: 1px solid #f3eee6;
}

th {
  color: #5c544b;
  font-weight: 400;
}

tbody tr:last-child td {
  border-bottom: none;
}

.facts {
  padding-top: 8px;
  padding-bottom: 64px;
}

.facts p {
  margin: 0;
  font-size: 16px;
  color: #5c544b;
  /* Avoid a single word alone on the last line. */
  text-wrap: pretty;
}

.fact-title {
  color: #2a2622;
  font-weight: 500;
}

/*
 * Below 1200px a third of the width is too narrow for the hero text,
 * so stack the hero and the notes in one column.
 */
@media (max-width: 1200px) {
  .hero,
  .facts {
    grid-template-columns: minmax(0, 1fr);
  }

  .preview {
    grid-column: auto;
  }

  .hero {
    row-gap: 40px;
    padding-top: 48px;
  }

  /* 540px keeps the paragraphs at 75 characters per line or fewer. */
  .hero-text,
  .preview,
  .facts p {
    max-width: 540px;
  }

  .facts {
    row-gap: 16px;
  }
}

@media (max-width: 900px) {
  :root {
    --page-gutter: 32px;
  }
}

/*
 * Phone: logo and "Sign in" share the top row, the other links go on
 * a second row. "display: contents" lets the nav's links sit directly
 * in the header's flex row while the nav element stays in the markup.
 * The empty ::after item takes a full row, which forces the line break.
 */
@media (max-width: 600px) {
  :root {
    --page-gutter: 20px;
  }

  .site-header {
    flex-wrap: wrap;
    gap: 10px 20px;
    padding-top: 14px;
    padding-bottom: 14px;
  }

  .site-header::after {
    content: "";
    order: 2;
    flex-basis: 100%;
    height: 0;
    margin-top: -10px;
  }

  .site-nav {
    display: contents;
  }

  .logo {
    order: 0;
    margin-right: auto;
  }

  .site-nav .nav-signin {
    order: 1;
  }

  .site-nav a {
    order: 3;
    margin-left: 0;
    white-space: nowrap;
  }

  h1 {
    font-size: 32px;
  }

  th,
  td {
    padding: 9px 10px;
  }

  /* Keep the column labels and the titles on one line each. */
  th,
  td:first-child {
    white-space: nowrap;
  }
}

